import { ref } from 'vue';

const OptimisticUI = {
  setup() {
    const items = ref(['Item 1', 'Item 2']);
    const isLoading = ref(false);

    const simulateApiCall = () => {
      return new Promise((resolve) => {
        setTimeout(() => {
          resolve('New Item');
        }, 1000);
      });
    };

    const optimisticUpdateHandler = async () => {
      const newItem = 'Optimistic Item';
      items.value.push(newItem);
      isLoading.value = true;

      try {
        const result = await simulateApiCall();
        const index = items.value.indexOf(newItem);
        if (index !== -1) {
          items.value[index] = result;
        }
      } catch (error) {
        console.error('API call failed:', error);
        const index = items.value.indexOf(newItem);
        if (index !== -1) {
          items.value.splice(index, 1);
        }
      } finally {
        isLoading.value = false;
      }
    };

    return { items, isLoading, optimisticUpdateHandler };
  },
  template: `
    <div>
      <button @click="optimisticUpdateHandler">Add Item</button>
      <ul>
        <li v-for="(item, index) in items" :key="index">{{ item }}</li>
      </ul>
    </div>
  `
};

export default OptimisticUI;

